using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Xml.Linq;using V15Voice;
public static class FeatureTests {
 static int count;static void Check(bool yes,string name){if(!yes)throw new Exception("FAIL "+name);Console.WriteLine("PASS "+name);count++;}
 static void Reject(Action f,string name){try{f();}catch{Check(true,name);return;}throw new Exception("FAIL "+name);}
 public static void Main(string[] args){string dir=Path.Combine(Path.GetTempPath(),"v15_feature_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);
  string a=Path.Combine(dir,"hello.txt"),b=Path.Combine(dir,"missing.txt"),store=Path.Combine(dir,"queue.xml");File.WriteAllText(a,"You thought it was a coincidence. But your brain noticed the pattern.");var j=BatchJob.Load(a);j.Cues[0].Text="This edited sentence must survive closing the application.";QueueStore.Save(store,new[]{j});var loaded=QueueStore.Load(store);Check(loaded.Count==1&&loaded[0].Cues[0].Text==j.Cues[0].Text,"Queue restores in-app edits without changing original source");Check(File.ReadAllText(a).StartsWith("You thought"),"Queue editing never rewrites source TXT");
  j.State=JobState.Running;QueueStore.Save(store,new[]{j});Check(QueueStore.Load(store)[0].State==JobState.Queued,"Interrupted active job is queued again after restart");
  j.CheckpointCues=j.Cues.Select(c=>new Cue{Start=c.Start,End=c.End,Text=c.Text}).ToList();j.Cues[0].End=.001;QueueStore.Save(store,new[]{j});Check(QueueStore.Load(store)[0].Cues[0].Text.StartsWith("This edited"),"Running checkpoint preserves edited script before partial flexible timing changes");j.Cues=j.CheckpointCues;j.CheckpointCues=null;
  j.State=JobState.Queued;BatchRunner.Run(new List<BatchJob>{j},false,()=>false,(job,file,notify)=>{job.Cues[0].End=.001;throw new Exception("test interruption");},(percent,message)=>{});Check(j.State==JobState.Failed&&j.Cues[0].End>.08&&j.CheckpointCues==null,"Failed batch restores pre-render cues for a safe retry");
  string wav=Path.ChangeExtension(a,"wav");new Wave{Rate=24000,Samples=new short[240]}.Write(wav);j.State=JobState.Done;j.OutputPath=wav;QueueStore.Save(store,new[]{j});Check(QueueStore.Load(store)[0].State==JobState.Done,"Completed existing WAV remains completed across restart");File.Delete(wav);Check(QueueStore.Load(store)[0].State==JobState.Queued,"Missing completed WAV is queued again");
  File.WriteAllText(a,"The source script changed and needs fresh narration.");loaded=QueueStore.Load(store);Check(loaded[0].State==JobState.Queued&&loaded[0].Cues[0].Text.StartsWith("The source"),"Changed source hash reloads script and invalidates completed result");
  var missing=BatchJob.Load(b);QueueStore.Save(store,new[]{missing});Check(QueueStore.Load(store)[0].State==JobState.ImportFailed,"Missing input is isolated as an import error");
  j=BatchJob.Load(a);QueueStore.Save(store,new[]{j});QueueStore.Save(store,new[]{j});File.WriteAllText(store,"<broken>");Check(QueueStore.Load(store).Count==1,"Damaged primary checkpoint falls back to atomic backup");
  string xxe=Path.Combine(dir,"xxe.xml");File.WriteAllText(xxe,"<!DOCTYPE x [<!ENTITY e SYSTEM 'file:///etc/passwd'>]><queue>&e;</queue>");Check(StateFiles.Read(xxe)==null,"Session loader rejects external XML entities");
  var setting=new VoiceSettings{Name="Review & kể chuyện",Key="Q:aiden",Speed=1.1,MaxSpeed=1.4,Gap=.2,Breathing=1,BreathEvery=4,BreathLevel=23,BreathPath="C:\\mẫu\\breath.wav",Join=true,Mode=1,BatchMode=2,Skip=false};var r=VoiceSettings.From(setting.Xml());Check(r.Name==setting.Name&&r.Key==setting.Key&&r.Speed==1.1&&r.MaxSpeed==1.4&&r.Gap==.2,"Preset roundtrip preserves voice and timing parameters");Check(r.Breathing==1&&r.BreathEvery==4&&r.BreathLevel==23&&r.BreathPath==setting.BreathPath&&r.Join&&!r.Skip&&r.BatchMode==2,"Preset roundtrip preserves breath, batch and sentence preferences");
  var source=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:03,300\nYour brain noticed something unusual\n\n2\n00:00:03,450 --> 00:00:06,750\nbefore you understood what was happening.\n\n3\n00:00:06,900 --> 00:00:10,200\nThen the pattern became clear.\n");string original=Scripts.ToSrt(source);var grouped=SpeechGroups.Join(source);Check(grouped.Count==2&&grouped[0].Text==source[0].Text+" "+source[1].Text,"Flexible sentence join combines only unfinished adjoining blocks");Check(Scripts.ToSrt(source)==original,"Joining creates a copy and preserves locked source timeline");source[1].Start=4;source[1].End=6.75;Check(SpeechGroups.Join(source).Count==3,"Sentence join does not bridge a deliberate long gap");Check(SpeechGroups.Inspect(source).Contains("nghỉ 0.70s"),"Preflight identifies long blank gaps");
  string state=Path.Combine(dir,"state");string id=Guid.NewGuid().ToString("N");var own=new VoiceProfile{Key="U:"+id,Name="Giọng thử & riêng",Gender="Nam",Kind=EngineKind.Qwen,ModelFolder="qwen_base",Styles="Review|Kể chuyện",Description="Ấm và trầm",ReferenceText="This is the exact reference transcript."};UserVoices.Save(state,own);var profile=UserVoices.Load(state).Single();Check(profile.Name==own.Name&&profile.ReferenceText==own.ReferenceText&&profile.Styles==own.Styles,"Custom voice names, transcript and style notes persist");Check(profile.ReferencePath==Path.Combine(state,"user_voices",id+".wav")&&profile.ModelFolder=="qwen_base","Voice reference resolves only inside private voice directory");
  var xml=StateFiles.Read(Path.Combine(state,"user_voices","voices.xml"));xml.Add(new XElement("voice",new XAttribute("id","../../escape"),new XAttribute("engine","Qwen")));StateFiles.Write(Path.Combine(state,"user_voices","voices.xml"),xml);Check(UserVoices.Load(state).Count==1,"Voice storage rejects path traversal identifiers");
  if(args.Length>0){string root=args[0];var e=new KokoroEngine{Root=root,Kind=EngineKind.Qwen,ModelFolder="qwen_custom",VoiceName="Aiden"};e.CheckFiles();Check(true,"Qwen bundled model and shared codec are present");e.Kind=EngineKind.Chatterbox;e.ModelFolder="chatter_nano";e.CheckFiles();Check(true,"Chatterbox bundled model and conditionals are present");e.ModelFolder="../escape";Reject(()=>e.CheckFiles(),"Unknown AI model directories are rejected");
   string mp3=Path.Combine(dir,"sample.mp3");var pi=new System.Diagnostics.ProcessStartInfo("ffmpeg","-nostdin -v error -y -stream_loop -1 -i "+KokoroEngine.Q(Path.Combine(root,"samples","03_Heart_US.wav"))+" -t 12 "+KokoroEngine.Q(mp3)){UseShellExecute=false,CreateNoWindow=true};using(var p=System.Diagnostics.Process.Start(pi))p.WaitForExit();Check(File.Exists(mp3),"MP3 conversion fixture was created");{var w=UserVoices.Import(root,mp3,Path.Combine(dir,"own.wav"),0,10,()=>false);Check(w.Duration>=6&&w.Rate==24000,"MP3 reference converts locally to a usable mono PCM WAV");Reject(()=>UserVoices.Import(root,mp3,Path.Combine(dir,"short.wav"),11,10,()=>false),"Too-short reference excerpts are rejected");Check(!File.Exists(Path.Combine(dir,"short.wav")),"Rejected reference conversion cleans partial WAV");}
  }
  Console.WriteLine("TOTAL "+count+" passed");
 }
}
